import 'package:drift/drift.dart';
import 'app_database.dart';

/// Stepwise migrations. Each future schema bump adds a `from: N` branch.
///
/// Foundation ships schema v1 only, so there are genuinely no upgrade steps
/// yet. `onUpgrade` is an explicit no-op rather than drift's `stepByStep()`
/// helper: `stepByStep()` requires schema-version code generated by the
/// `drift_dev schema` CLI, and that CLI does not compile in this environment
/// (drift_dev 2.34.0 against drift 2.34.2). A later sub-project introducing
/// schema v2 should replace this no-op with real stepwise migrations.
MigrationStrategy buildMigration(AppDatabase db) => MigrationStrategy(
      onCreate: (m) async {
        await m.createAll();
        await db.into(db.appMetaTable).insert(
              AppMetaTableCompanion.insert(installedAt: DateTime.now()),
            );
        await db
            .into(db.appSettingsTable)
            .insert(const AppSettingsTableCompanion());
      },
      onUpgrade: (Migrator m, int from, int to) async {},
      beforeOpen: (details) async {
        await db.customStatement('PRAGMA foreign_keys = ON');
      },
    );
